/**
 * Translate with a real fallback.
 *
 * `salla.lang.get(key, replacements, locale)` takes a LOCALE as its third
 * argument, not a fallback, and lang.js echoes the key back when it has no
 * translation. Passing a fallback there silently asks for a nonsense locale and
 * still renders the raw key to the customer, which is what a store shows while
 * its translation bundle has not yet picked up newly added keys.
 */
export function translate(key, replacements, fallback) {
    const value = salla.lang.get(key, replacements);
    return !value || value === key ? fallback : value;
}
